/**
 *
 * ToastContent is a layout wrapper that holds the icon and content within a Toast.
 *
 * [Live Demo](https://www.primereact.org/toast/)
 *
 * @module ToastContent
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ToastRootInstance } from './ToastRoot.types';
/**
 * Defines passthrough(pt) options type in ToastContent component.
 */
export type ToastContentPassThroughType<E> = PassThroughType<ToastContentInstance, E>;
/**
 * Defines passthrough(pt) options of ToastContent component.
 */
export interface ToastContentPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ToastContentPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in ToastContent component.
 */
export interface ToastContentProps extends BaseComponentProps<ToastContentInstance, unknown, ToastContentPassThrough> {
}
/**
 * Defines valid state in ToastContent component.
 */
export interface ToastContentState {
}
/**
 * Defines the methods and properties exposed by ToastContent component.
 */
export interface ToastContentExposes {
    /**
     * The Toast component instance.
     */
    toast: ToastRootInstance | undefined | null;
}
/**
 * Instance of ToastContent component.
 */
export type ToastContentInstance = ComponentInstance<ToastContentProps, ToastContentState, ToastContentExposes>;
